package msdelta

import (
	"encoding/base64"
	"testing"
)

// Windows msdelta.dll reverse oracle fixtures from CaddyGlow/ms-delta;
// reviewed at 6f25d63e8a8573015feb2f6a3d3f98861edbb22c. See playback.LICENSE
// and docs/third-party-format-references.md for input origins and delta hashes.
// The PA31 envelope includes independent SHA-256 hashes.
func TestPlaybackNativeOracles(t *testing.T) {
	for _, tc := range []struct{ name, source, delta string }{
		{"amd64", "", ""},
		{"empty", "", "UEEzMQAAAAAAAAAAMApgQAxAAAAAiIAMgIIA47DEQpj8HBSa+/TImW+5JCeuQeRkm5NMpJWZG3hSuFUijiAI47DEQpj8HBSa+/TImW+5JCeuQeRkm5NMpJWZG3hSuFWuAICSmmoKAAAAmAQAAAAIAAAAAB0IAAAACAAAAAAAAAAQABMUAAAACAAAAAA="},
		{"abc", "YWJj", "UEEzMQAAAAAAAAAAMApgQAxAAAAAiIAMgIIA47DEQpj8HBSa+/TImW+5JCeuQeRkm5NMpJWZG3hSuFUijiAIungWv48Bz+pBQUDeXa4iI7ADYaOWF3qctBD/YfIAFa2uAICSmmoKAAAAmAQAAAAIAAAAAB0IAAAACAAAAAAAAAAQABMUAAAACAAAAAA="},
		{"compressed-delete", "ZW5k", ""},
		{"managed", "", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			decode := func(s string) []byte {
				b, e := base64.StdEncoding.DecodeString(s)
				if e != nil {
					t.Fatal(e)
				}
				return b
			}
			source, delta := decode(tc.source), decode(tc.delta)
			header, err := Parse(delta)
			if err != nil {
				t.Fatal(err)
			}
			got, err := ApplyBounded(source, delta, header.TargetSize)
			if err != nil || uint64(len(got)) != header.TargetSize {
				t.Fatalf("size %d, error %v", len(got), err)
			}
			for n := 0; n < len(delta); n++ {
				if _, e := ApplyBounded(source, delta[:n], header.TargetSize); e == nil {
					t.Fatalf("accepted truncation at %d", n)
				}
			}
		})
	}
}
